import "fake-indexeddb/auto"
import { beforeEach, expect, test, vi } from "vitest"
import { createRelayInvitation, listRelayDevices, requestRelayHostGrant } from "./relay-management"

const { authenticateMock, identityMock } = vi.hoisted(() => ({
  authenticateMock: vi.fn(),
  identityMock: vi.fn(),
}))
vi.mock("./relay-client", async importOriginal => ({
  ...await importOriginal<typeof import("./relay-client")>(),
  authenticateRelayDevice: authenticateMock,
}))
vi.mock("./device-identity", () => ({ deviceIdentity: identityMock }))

const options = {
  managementUrl: "http://127.0.0.1:8080/",
  webSocketUrl: "ws://127.0.0.1:8081/relay/v1",
  tenantId: "tenant-1",
  hostId: "host-1",
}

beforeEach(() => {
  localStorage.clear()
  sessionStorage.clear()
  authenticateMock.mockReset().mockResolvedValue("short-lived-access")
  identityMock.mockReset().mockResolvedValue({ deviceId: "device-1" })
})

test("uses ephemeral challenge token for invitation and device management", async () => {
  const requests: Array<{ url: string; authorization: string; body?: string }> = []
  vi.stubGlobal("fetch", vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    requests.push({ url: String(input), authorization: String(new Headers(init?.headers).get("Authorization")), body: String(init?.body ?? "") })
    if (String(input).endsWith("/api/v1/invitations")) return response({
      invitationId: "invite-1", secret: "single-use-secret", fingerprint: "aa-bb-cc",
      expiresAt: "2026-09-06T01:00:00Z", hostIds: ["host-1"],
    }, 201)
    return response({ devices: [{ deviceId: "device-1", authAlgorithm: "ecdsa-p256-sha256-spki", roles: ["RELAY_OWNER"], active: true, createdAt: "2026-09-06T00:00:00Z" }] })
  }))

  expect((await createRelayInvitation(options, ["host-1"])).fingerprint).toBe("aa-bb-cc")
  expect(await listRelayDevices(options)).toHaveLength(1)
  expect(requests.every(request => request.authorization === "Bearer [REDACTED_CREDENTIAL]")).toBe(true)
  expect(JSON.stringify(localStorage)).not.toContain("short-lived-access")
  expect(JSON.stringify(sessionStorage)).not.toContain("short-lived-access")
  expect(localStorage.length).toBe(0)
  expect(sessionStorage.length).toBe(0)
})

test("requests only Relay route metadata and keeps Host role out of the request", async () => {
  let body: Record<string, unknown> | undefined
  vi.stubGlobal("fetch", vi.fn(async (_input: RequestInfo | URL, init?: RequestInit) => {
    body = JSON.parse(String(init?.body)) as Record<string, unknown>
    return response({ status: "requested" }, 201)
  }))

  await requestRelayHostGrant(options, "host-1")
  expect(body).toEqual({ deviceId: "device-1", requestedScopes: ["host:request"] })
  expect(JSON.stringify(body)).not.toMatch(/controller|observer|admin/i)
})

function response(body: unknown, status = 200) {
  return Promise.resolve(new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } }))
}
